func (s *StudentDocuments) QueueStudentDocumentFileCleanup(ctx context.Context, studentID int64, storedName string) error {
	if studentID <= 0 || strings.TrimSpace(storedName) == "" {
		return fmt.Errorf("%w: cleanup file details are required", careplan.ErrStudentDocumentInvalid)
	}
	cleanup := careplan.CareDocumentCleanup{OwnerID: studentID, FilenameStored: storedName, RetryAfter: time.Now().Add(studentDocumentCleanupDelay)}
	return s.transaction(ctx, func(txCtx context.Context) error {
		_, err := s.records.QueueCareDocumentCleanup(txCtx, cleanup)
		return err
	})
}

func (s *StudentDocuments) ResolveStudentDocumentCleanup(ctx context.Context, studentID, documentID int64, actor careplan.StudentDocumentActor) (careplan.CareDocument, error) {
	if err := s.requireStudentAccess(ctx, studentID, actor); err != nil {
		return careplan.CareDocument{}, err
	}
	document, err := s.records.FindCareDocument(ctx, studentID, documentID, true)
	if err != nil {
		return careplan.CareDocument{}, err
	}
	if err := s.requireCategoryPermission(document.Category, actor); err != nil {
		return careplan.CareDocument{}, err
	}
	return document, nil
}

