func (t targets) CountOrganizationsByID(ctx context.Context, ids []int64) (int, domain.OperationStats, error) {
	count, err := t.capability.CountOrganizationsByID(ctx, ids)
	stats := domain.OperationStats{Queries: 1, Rows: int64(count)}
	if errors.Is(err, organizationtenancy.ErrInvalidOrganization) {
		return 0, stats, fmt.Errorf("%w: %v", errInvalidTarget, err)
	}
	return count, stats, err
}

func (t targets) CountSchoolsByID(ctx context.Context, ids []int64) (int, domain.OperationStats, error) {
	count, err := t.capability.CountSchoolsByID(ctx, ids)
	stats := domain.OperationStats{Queries: 1, Rows: int64(count)}
	if errors.Is(err, organizationtenancy.ErrInvalidSchool) {
		return 0, stats, fmt.Errorf("%w: %v", errInvalidTarget, err)
	}
	return count, stats, err
}

func (e *EventEmitter) InTransaction(ctx context.Context) bool {
	if e == nil || e.runtime == nil {
		return false
	}
	return e.runtime.InTransaction(ctx)
}

func (s *Service) CountScope(ctx context.Context) (string, error) {
	if s.CountPreferences == nil {
		return CountScopeAll, nil
	}
	scope, err := s.CountPreferences.CountScope(ctx, s.accountID(ctx))
	if err != nil {
		return "", fmt.Errorf("messaging: load count scope: %w", err)
	}
	if !validCountScope(scope) {
		return CountScopeAll, nil
	}
	return scope, nil
}

func (s *Service) HasOwnGroups(ctx context.Context) (bool, error) {
	if s.Groups == nil {
		return false, nil
	}
	groupIDs, err := s.Groups.MyGroupIDs(ctx)
	if err != nil {
		return false, fmt.Errorf("messaging: resolve own groups: %w", err)
	}
	return len(groupIDs) > 0, nil
}

func (s *Service) ListGuardians(ctx context.Context, studentID int64) ([]*MessageableGuardian, error) {
	if err := s.canReadStudent(ctx, studentID); err != nil {
		return nil, err
	}
	guardians, err := s.ThreadRepo.ListGuardiansForStudent(ctx, studentID)
	if err != nil {
		return nil, fmt.Errorf("messaging: list guardians: %w", err)
	}
	return guardians, nil
}

func (s *Service) ListParentGroupThreads(ctx context.Context) ([]deliveryPorts.ParentGroupThreadSummary, error) {
	if err := s.requireGroupAuthor(ctx); err != nil {
		return nil, err
	}
	rows, err := s.GroupThreads.ListThreads(ctx)
	if err != nil {
		return nil, fmt.Errorf("messaging: list group threads: %w", err)
	}
	return rows, nil
}

func (s *Service) ListReachableStudentIDs(ctx context.Context) ([]int64, error) {
	if !s.scope(ctx) {
		return nil, ErrForbidden
	}
	ids, err := s.ThreadRepo.ListStudentIDsWithMessageableGuardian(ctx)
	if err != nil {
		return nil, fmt.Errorf("messaging: list reachable students: %w", err)
	}
	return ids, nil
}

func (s *Service) ListStudentThreads(ctx context.Context, studentID int64) ([]*InboxThread, error) {
	if err := s.canReadStudent(ctx, studentID); err != nil {
		return nil, err
	}
	rows, err := s.ReadRepo.ListThreadsForStudent(ctx, s.accountID(ctx), studentID)
	if err != nil {
		return nil, fmt.Errorf("messaging: list student threads: %w", err)
	}
	s.suppressDisabledUnread(ctx, rows)
	return rows, nil
}

func (s *Service) MarkUnread(ctx context.Context, threadID int64) error {
	thread, err := s.loadAuthorizedThread(ctx, threadID)
	if err != nil {
		return err
	}
	if err := s.ReadRepo.MarkStaffUnread(ctx, thread.TenantID, thread.ID, s.accountID(ctx)); err != nil {
		return fmt.Errorf("messaging: mark unread: %w", err)
	}
	s.broadcastStaffUnreadAfterCommit(ctx, thread)
	return nil
}

func (s *Service) SetCountScope(ctx context.Context, scope string) error {
	if !validCountScope(scope) {
		return ErrInvalidCountScope
	}
	if s.CountPreferences == nil {
		return errors.New("messaging: count preference store is not configured")
	}
	if err := s.CountPreferences.SetCountScope(ctx, s.accountID(ctx), scope); err != nil {
		return fmt.Errorf("messaging: save count scope: %w", err)
	}
	return nil
}

