	return moved, RetainedStudentWriteError(MapError(err))
}

func (w *StudentRecords) Update(ctx context.Context, student *peopleModule.StudentState) error {
	if student == nil {
		return errors.New("student cannot be nil")
	}
	if student.ID <= 0 {
		return RetainedStudentWriteError(&peopleModule.InvalidStudentError{Reason: "student ID is required"})
	}
	record, err := w.directory.UpdateStudent(ctx, toApplicationStudentWrite(StudentWriteFromModel(student)))
	if err != nil {
		return RetainedStudentWriteError(MapError(err))
	}
	ApplyStudentRecord(student, peopleModule.StudentRecord(record))
	return nil
}

func (w *StudentRecords) UpdateStatus(ctx context.Context, studentID int64, status string) error {
	changed, err := w.membership.SetStatus(ctx, studentID, string(status))
	if err == nil && !changed {
		err = peopleModule.ErrStudentNotFound
	}
	return RetainedStudentWriteError(MapError(err))
}

func (w *StudentRecords) VerifyCompanionStrandingBatch(ctx context.Context) error {
	return RetainedStudentWriteError(MapError(w.directory.VerifyStrandingBatch(ctx)))
}

func (p StudentRoutePersons) AssignStudentTag(ctx context.Context, studentID int64, tagID string) error {
	err := p.persons.LinkStudentToRFIDCard(ctx, studentID, tagID)
	if errors.Is(err, userscontract.ErrStudentGraduated) || errors.Is(err, userscontract.ErrStudentNotFound) {
		return errors.Join(peopleModule.ErrStudentNotFound, err)
	}
	return err
}

func (p StudentRoutePersons) CreatePerson(ctx context.Context, input peopleModule.CreatePerson) (peopleModule.Person, error) {
	person := &peopleModule.DirectoryPersonSnapshot{FirstName: input.FirstName, LastName: input.LastName, Birthday: peopleModule.OptionalCalendarDate(input.Birthday), TagID: input.TagID, AccountID: input.AccountID}
	if err := p.persons.Create(ctx, person); err != nil {
		return peopleModule.Person{}, err
	}
	return studentRoutePerson(person), nil
}

func (p StudentRoutePersons) ListStudentsForDay(ctx context.Context, groupIDs []int64, date, today calendar.Date) ([]peopleModule.StudentRecord, error) {
	students, err := p.persons.GetEligibleStudentsByGroupIDsOnDate(ctx, groupIDs, date, today)
	if err != nil {
		return nil, err
	}
	records := make([]peopleModule.StudentRecord, 0, len(students))
	for _, student := range students {
		if student != nil {
			records = append(records, studentRouteRecord(student))
		}
	}
	return records, nil
}

func (p StudentRoutePersons) StaffIDForPerson(ctx context.Context, personID int64) (int64, bool, error) {
	staff, err := p.persons.StaffRows().FindByPersonID(ctx, personID)
	if err != nil {
		var notFound interface{ RepositoryNotFound() }
		if errors.As(err, &notFound) {
			return 0, false, nil
		}
		return 0, false, err
	}
	if staff == nil {
		return 0, false, nil
	}
	return staff.ID, true, nil
}

func (p StudentRoutePersons) UpdatePerson(ctx context.Context, input peopleModule.UpdatePerson) (peopleModule.Person, error) {
	person := &peopleModule.DirectoryPersonSnapshot{FirstName: input.FirstName, LastName: input.LastName, Birthday: peopleModule.OptionalCalendarDate(input.Birthday), TagID: input.TagID, AccountID: input.AccountID}
	person.ID = input.ID
	if err := p.persons.Update(ctx, person); err != nil {
		return peopleModule.Person{}, err
	}
	return studentRoutePerson(person), nil
}

