		if id <= 0 || at.IsZero() || updatedAt.IsZero() {
			return ports.Stats{}, errors.New("student presence: invalid stale attendance close")
		}
		stats, writeErr := s.store.CloseStaleAttendance(txCtx, id, at, updatedAt)
		if writeErr == nil {
			result = stats.Rows
		}
		return stats, writeErr
	})
	return result, err
}

