			return ports.Stats{}, errors.New("student presence: invalid bulk activity session completion")
		}
		stats, completeErr := s.store.CompleteActivitySessionsByGroups(txCtx, activeGroupIDs, at)
		result = stats.Rows
		return stats, completeErr
	})
	return result, err
