func (g *ActiveGroup) GetDuration() time.Duration {
	if g.EndTime == nil {
		return time.Since(g.StartTime)
	}
	return g.EndTime.Sub(g.StartTime)
}

func (g *ActiveGroup) SetEndTime(endTime time.Time) error {
	if g.StartTime.After(endTime) {
		return errors.New("end time cannot be before start time")
	}
	g.EndTime = &endTime
	return nil
}

func (gs *GroupSupervisor) SetEndDate(endDate Date) error {
	if gs.StartDate.After(endDate) {
		return errors.New("end date cannot be before start date")
	}
	gs.EndDate = &endDate
	return nil
}

func (v ClassArrivalExceptionInput) Valid() bool {
	return strings.TrimSpace(v.SchoolClass) != "" && ValidDate(v.Date) && !v.ArrivalTime.IsZero() && (v.Reason == nil || utf8.RuneCountInString(*v.Reason) <= 255) && (v.CreatedBy == nil || *v.CreatedBy > 0) && (v.Origin == "" || v.Origin == "ogs" || v.Origin == "school")
}

